import{_ as e,o as a,c as l,a2 as o}from"./chunks/framework.RycU2wFZ.js";const x=JSON.parse('{"title":"ADR-001: x402 V2 协议与官方 SDK 架构策略（“复用 vs. 自研实现”）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specs/adr/001.md","filePath":"zh/specs/adr/001.md","lastUpdated":null}'),r={name:"zh/specs/adr/001.md"};function n(i,t,s,d,c,g){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="adr-001-x402-v2-协议与官方-sdk-架构策略-复用-vs-自研实现" tabindex="-1">ADR-001: x402 V2 协议与官方 SDK 架构策略（“复用 vs. 自研实现”） <a class="header-anchor" href="#adr-001-x402-v2-协议与官方-sdk-架构策略-复用-vs-自研实现" aria-label="Permalink to &quot;ADR-001: x402 V2 协议与官方 SDK 架构策略（“复用 vs. 自研实现”）&quot;">​</a></h1><ul><li><strong>状态：</strong> 已采纳 (Accepted)</li><li><strong>日期：</strong> 2026-10-16</li><li><strong>决策者：</strong> AgentPay 核心架构工作组</li><li><strong>关联任务：</strong> 2026 年底规划 (任务 T0.2, T3.1)</li></ul><hr><h2 id="_1-背景与问题陈述" tabindex="-1">1. 背景与问题陈述 <a class="header-anchor" href="#_1-背景与问题陈述" aria-label="Permalink to &quot;1. 背景与问题陈述&quot;">​</a></h2><p>x402 是针对 HTTP 402 Payment Required 微支付的开放标准协议（由 x402 基金会维护）。在当前 2026 生态中：</p><ol><li><strong>协议规范现状：</strong> x402 V2 规范定义了 CAIP-2 链标识符、EIP-712/3009 转账授权，以及结构化的 <code>PAYMENT-REQUIRED</code> 与 <code>PAYMENT-SIGNATURE</code> 请求头。</li><li><strong>官方 Python SDK 现状：</strong> PyPI 上已存在基础的 <code>x402</code> 包（含 <code>x402[httpx]</code>、<code>x402[requests]</code> 等可选扩展），提供基础的挑战提取与原始签名绑定。</li><li><strong>AgentPay 核心差异化定位：</strong><ul><li>官方 SDK 本质上是一个<strong>原始传输层封装（Raw Transport Wrapper）</strong>：只要遇到 HTTP 402，就会无条件签名并付款。</li><li>AgentPay 则定位为<strong>自主金融防火墙与容错基础设施层（Autonomous Financial Firewall &amp; Fault-Tolerant Infrastructure Layer）</strong>：其核心价值在于<strong>确定性策略评估（单笔上限、滚动预算、白名单、循环熔断器与两阶段原子预留）<strong>以及</strong>解耦的三态恢复引擎</strong>。</li></ul></li></ol><hr><h2 id="_2-备选方案评估" tabindex="-1">2. 备选方案评估 <a class="header-anchor" href="#_2-备选方案评估" aria-label="Permalink to &quot;2. 备选方案评估&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">评估维度</th><th style="text-align:left;">方案 A：强依赖官方 SDK (<code>x402</code>)</th><th style="text-align:left;">方案 B：完全从零自研实现</th><th style="text-align:left;">方案 C（推荐）：分层适配 + 自研防火墙核心</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>金融防火墙集成</strong></td><td style="text-align:left;">困难。官方拦截器缺少两阶段预留（<code>reserve -&gt; commit -&gt; release</code>）生命周期钩子。</td><td style="text-align:left;">完全自主；拦截器与策略引擎无缝协同。</td><td style="text-align:left;"><strong>优秀。</strong> 完整生命周期拦截器，且与上游协议格式严格对齐。</td></tr><tr><td style="text-align:left;"><strong>依赖体积与冲突</strong></td><td style="text-align:left;">笨重。容易引入传递性的 web3 与加密库版本冲突。</td><td style="text-align:left;">极简（<code>httpx</code>、<code>pydantic</code>、<code>eth-account</code>）。</td><td style="text-align:left;"><strong>极简。</strong> 核心包零冗余依赖，官方 SDK 仅作为纯可选扩展。</td></tr><tr><td style="text-align:left;"><strong>上游规范对齐度</strong></td><td style="text-align:left;">自动继承上游补丁。</td><td style="text-align:left;">协议头变更时需手动对齐。</td><td style="text-align:left;"><strong>高。</strong> 标准 Pydantic 模型通过上游测试向量持续验证。</td></tr><tr><td style="text-align:left;"><strong>实现风险与开发效率</strong></td><td style="text-align:left;">初期快但改造防火墙状态机风险高。</td><td style="text-align:left;">适中（约 200 行 Pydantic 编解码）。</td><td style="text-align:left;"><strong>最优（约 3 小时完成清晰模型，零黑盒调试成本）。</strong></td></tr></tbody></table><hr><h2 id="_3-决策结果" tabindex="-1">3. 决策结果 <a class="header-anchor" href="#_3-决策结果" aria-label="Permalink to &quot;3. 决策结果&quot;">​</a></h2><p>我们决定采用 <strong>方案 C（分层适配架构）</strong>：</p><h3 id="_3-1-核心协议编解码-agentpay-core-—-原生-pydantic-v2-模型" tabindex="-1">3.1 核心协议编解码 (<code>agentpay-core</code>) — 原生 Pydantic V2 模型 <a class="header-anchor" href="#_3-1-核心协议编解码-agentpay-core-—-原生-pydantic-v2-模型" aria-label="Permalink to &quot;3.1 核心协议编解码 (`agentpay-core`) — 原生 Pydantic V2 模型&quot;">​</a></h3><ul><li>我们<strong>不</strong>将第三方 <code>x402</code> PyPI 包作为强依赖。</li><li>使用 <strong>Pydantic V2</strong> 原生定义 <code>PaymentChallenge</code> 与 <code>PaymentAuthorization</code> 模型，严格遵循 x402 V2 标准。</li><li><strong>100% 字节级一致：</strong> 序列化与反序列化行为通过标准测试向量（<code>specs/conformance/test-vectors/</code>）验证。</li><li><strong>收益：</strong> 消除依赖冲突与运行时黑盒，保证最佳测试执行速度与透明调试体验。</li></ul><h3 id="_3-2-网络拦截器与签名生命周期-agentpay-client-—-自研编排" tabindex="-1">3.2 网络拦截器与签名生命周期 (<code>agentpay-client</code>) — 自研编排 <a class="header-anchor" href="#_3-2-网络拦截器与签名生命周期-agentpay-client-—-自研编排" aria-label="Permalink to &quot;3.2 网络拦截器与签名生命周期 (`agentpay-client`) — 自研编排&quot;">​</a></h3><ul><li>实现自主可控的 <code>httpx</code> 传输层拦截器。</li><li>客户端严格编排完整的金融生命周期： $$\\text{拦截 402} \\longrightarrow \\text{策略评估与预算预留} \\longrightarrow \\text{签署授权} \\longrightarrow \\text{携带 PAYMENT-SIGNATURE 重放} \\longrightarrow \\text{提交或释放预留}$$</li></ul><h3 id="_3-3-上游互操作扩展-x402-interop-—-可选扩展" tabindex="-1">3.3 上游互操作扩展 (<code>x402-interop</code>) — 可选扩展 <a class="header-anchor" href="#_3-3-上游互操作扩展-x402-interop-—-可选扩展" aria-label="Permalink to &quot;3.3 上游互操作扩展 (`x402-interop`) — 可选扩展&quot;">​</a></h3><ul><li>提供辅助转换工具，支持在 AgentPay 原生挑战/授权对象与官方 <code>x402</code> 库对象之间双向转换，确保同时安装两者的用户可无缝互操作。</li></ul><hr><h2 id="_4-后续影响与风险应对" tabindex="-1">4. 后续影响与风险应对 <a class="header-anchor" href="#_4-后续影响与风险应对" aria-label="Permalink to &quot;4. 后续影响与风险应对&quot;">​</a></h2><ul><li><strong>正向影响：</strong><ul><li>任务 T3.1 的实现工作量严格可控（$\\le 3$ 小时）。</li><li>两阶段预留（<code>reserve -&gt; commit -&gt; release</code>）直接内嵌到 HTTP 传输生命周期中，无需侵入式 Hack。</li><li>Python SDK 保持极度轻量，冷启动极快。</li></ul></li><li><strong>风险与缓解：</strong><ul><li><strong>风险：</strong> 上游 x402 V2 规范发生破坏性 Schema 变更。</li><li><strong>缓解：</strong> 在 GitHub Actions 中使用跨语言 JSON 测试向量执行持续自动化一致性测试，及时捕获 Schema 漂移。</li></ul></li></ul>',21)])])}const y=e(r,[["render",n]]);export{x as __pageData,y as default};
